package com.interview.patterns.visitor;

public sealed interface Expression permits NumberExpression, AddExpression, MultiplyExpression {}

record NumberExpression(double value) implements Expression {}
record AddExpression(Expression left, Expression right) implements Expression {}
record MultiplyExpression(Expression left, Expression right) implements Expression {}

package com.interview.patterns.visitor;

public class ExpressionEvaluator {
    public double evaluate(Expression expr) {
        return switch (expr) {
            case NumberExpression(double v) -> v;
            case AddExpression(Expression left, Expression right) -> evaluate(left) + evaluate(right);
            case MultiplyExpression(Expression left, Expression right) -> evaluate(left) * evaluate(right);
        };
    }
}

