import static org.junit.jupiter.api.Assertions.assertEquals;

public class TimedOrderRepositoryTest {
    @Test
    public void testDecorator() {
        var impl = new OrderRepositoryImpl();
        var timed = new TimedOrderRepository(impl);
        assertEquals("ORDER_DATA_ord_99", timed.findOrderById("ord_99"));
    }
}

