package com.interview.patterns.decorator;

public class TimedOrderRepository implements OrderRepository {
    private final OrderRepository delegate;

    public TimedOrderRepository(OrderRepository delegate) {
        this.delegate = delegate;
    }

    @Override
    public String findOrderById(String orderId) {
        long start = System.currentTimeMillis();
        try {
            return delegate.findOrderById(orderId);
        } finally {
            long duration = System.currentTimeMillis() - start;
        }
    }
}
